package featurecat.lizzie.rules;

import com.sun.management.ThreadMXBean;
import featurecat.lizzie.Lizzie;
import java.lang.management.ManagementFactory;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.HexFormat;
import java.util.concurrent.FutureTask;
import java.util.concurrent.TimeUnit;
import javax.swing.SwingUtilities;
import org.json.JSONArray;
import org.json.JSONObject;

/** One-off measurement of snapshot work; no file-open latency or painting claim. */
public final class GameEditSnapshotCostProbe {
  public static void main(String[] args) throws Exception {
    try {
      run(args);
      System.exit(0);
    } catch (Throwable failure) {
      failure.printStackTrace();
      System.exit(1);
    }
  }

  private static void run(String[] args) throws Exception {
    Path fixtures = Path.of(args[0]);
    Path output = Path.of(args[1]);
    int samples = Integer.parseInt(args[2]);
    int warmups = Integer.parseInt(args[3]);
    if (Files.exists(output) || samples < 1 || warmups < 0) throw new IllegalArgumentException();
    ThreadMXBean bean = (ThreadMXBean) ManagementFactory.getThreadMXBean();
    if (!bean.isThreadCpuTimeSupported() || !bean.isThreadAllocatedMemorySupported()) {
      throw new IllegalStateException("CPU and allocation accounting are required");
    }
    bean.setThreadCpuTimeEnabled(true);
    bean.setThreadAllocatedMemoryEnabled(true);
    JSONArray groups = new JSONArray();
    JSONObject result = new JSONObject()
        .put("started", Instant.now().toString())
        .put("samples", samples).put("warmupsExcluded", warmups)
        .put("measurement", "One capture followed by one full isCurrent call, each measured on the EDT; repeated same-history hot-cache work, not an interactive open")
        .put("fixtureSource", "Existing actual-window SgfPerformanceProbe fixtures; file-import history builder with RulesLayerTestHarness, no live window or engine")
        .put("jvm", System.getProperty("java.runtime.version"))
        .put("os", System.getProperty("os.name") + " " + System.getProperty("os.version"))
        .put("jvmArgs", ManagementFactory.getRuntimeMXBean().getInputArguments())
        .put("logicalProcessors", Runtime.getRuntime().availableProcessors())
        .put("columns", new JSONArray(new String[] {"sampleIndex", "captureWallMs", "captureCpuMs",
            "captureAllocatedBytes", "validationWallMs", "validationCpuMs", "validationAllocatedBytes"}))
        .put("groups", groups);
    JSONObject original = new JSONObject(Files.readString(fixtures.resolve("summary.json")));
    for (Object value : original.getJSONArray("fixtures")) {
      JSONObject expected = (JSONObject) value;
      String name = expected.getString("name");
      Path file = fixtures.resolve(name + ".sgf");
      byte[] bytes = Files.readAllBytes(file);
      String hash = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
      if (!hash.equals(expected.getString("sha256"))) throw new AssertionError("Fixture mismatch");
      JSONArray rows = new JSONArray();
      FutureTask<Void> task = new FutureTask<>(() -> {
        try (var fixture = RulesLayerTestHarness.open(19)) {
          Lizzie.config.limitMaxSuggestion = 0;
          Lizzie.config.limitBranchLength = 0;
          var prepared = SGFParser.prepareFileGame(
              SGFParser.prepareFileContent(Files.readString(file)), SGFParser.ParseOptions.capture());
          // Inspect the existing private file-import history only for this diagnostic.
          var field = SGFParser.PreparedGame.class.getDeclaredField("history");
          field.setAccessible(true);
          var history = (BoardHistoryList) field.get(prepared);
          fixture.board().setHistory(history);
          history.setHead(history.getEnd());
          int count = 0;
          var pending = new ArrayDeque<BoardHistoryNode>();
          pending.add(history.getStart());
          while (!pending.isEmpty()) {
            BoardHistoryNode node = pending.removeFirst();
            count++;
            pending.addAll(node.getVariations());
          }
          if (count != expected.getInt("expectedNodes")) throw new AssertionError("Node mismatch");
          long thread = Thread.currentThread().getId();
          for (int i = -warmups; i < samples; i++) {
            long allocated = bean.getThreadAllocatedBytes(thread);
            long cpu = bean.getCurrentThreadCpuTime();
            long start = System.nanoTime();
            GameEditSnapshot snapshot = GameEditSnapshot.capture(fixture.board());
            long captureWall = System.nanoTime() - start;
            long captureCpu = bean.getCurrentThreadCpuTime() - cpu;
            long captureAllocated = bean.getThreadAllocatedBytes(thread) - allocated;
            allocated = bean.getThreadAllocatedBytes(thread);
            cpu = bean.getCurrentThreadCpuTime();
            start = System.nanoTime();
            boolean current = snapshot.isCurrent(fixture.board());
            long validationWall = System.nanoTime() - start;
            long validationCpu = bean.getCurrentThreadCpuTime() - cpu;
            long validationAllocated = bean.getThreadAllocatedBytes(thread) - allocated;
            if (!current) throw new AssertionError("Unchanged game rejected");
            rows.put(new JSONArray().put(i).put(captureWall / 1e6).put(captureCpu / 1e6)
                .put(captureAllocated).put(validationWall / 1e6).put(validationCpu / 1e6)
                .put(validationAllocated));
          }
          groups.put(new JSONObject().put("fixture", name).put("sha256", hash)
              .put("nodes", count).put("thread", Thread.currentThread().getName()).put("samples", rows));
        }
        return null;
      });
      SwingUtilities.invokeLater(task);
      task.get(180, TimeUnit.SECONDS);
      Files.writeString(output, result.toString(2) + "\n");
      System.out.println(name + " PASS");
    }
    result.put("finished", Instant.now().toString()).put("result", "PASS");
    Files.writeString(output, result.toString(2) + "\n");
  }
}
